-- orders, fragment punct-3 'a.b', page 2
-- cost variable: hits = 36835 (scales with orders)
SELECT o.id, o.number, o.placed_at, o.status, o.email, o.full_name, o.total_gross, o.currency, (SELECT COALESCE(SUM(l.quantity), 0) FROM ordering_order_line l WHERE l.order_id = o.id) AS item_count, o.refund_amount, o.refund_due_at, o.refund_completed_at FROM ordering_order o WHERE lower(o.number || E'\x1f' || o.email || E'\x1f' || o.full_name) LIKE '%' || lower('a.b') || '%' AND (o.placed_at, o.id) < (CAST('2026-11-26 17:09:23+00' AS timestamptz), CAST('01a218d5-51b8-7ae1-aa29-c67898007c8b' AS uuid)) ORDER BY o.placed_at DESC, o.id DESC LIMIT 26;
